mkdir -p /tmp/rls-test && cat > /tmp/rls-test/setup.sql <<'EOF'
create role anon nologin;
create role authenticated nologin;
create schema auth;
create table auth.users (id uuid primary key);
create function auth.uid() returns uuid language sql stable as
  $$ select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
grant usage on schema public, auth to anon, authenticated;
grant all on all tables in schema public to anon, authenticated;
alter default privileges in schema public grant all on tables to anon, authenticated;
EOF
cat > /tmp/rls-test/tests.sql <<'EOF'
\set ON_ERROR_STOP 0
insert into auth.users values ('00000000-0000-0000-0000-00000000000a'),('00000000-0000-0000-0000-00000000000b'),('00000000-0000-0000-0000-00000000000c');
insert into public.teams (id,name) values ('10000000-0000-0000-0000-000000000001','A'),('10000000-0000-0000-0000-000000000002','B');
insert into public.team_members values
 ('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-00000000000a','admin'),
 ('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-00000000000b','member'),
 ('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-00000000000c','admin');
insert into public.projects (id,team_id,name) values
 ('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','pA'),
 ('20000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000002','pB');

\echo '== anon sees nothing'
set role anon;
select 'teams' t, count(*) from public.teams union all select 'members', count(*) from public.team_members union all select 'projects', count(*) from public.projects union all select 'overview', count(*) from public.project_overview;
reset role;

\echo '== member A (b) sees team A only'
set role authenticated; set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
select 'teams' t, string_agg(name,',') from public.teams;
select 'members', count(*) from public.team_members;
select 'projects', string_agg(name,',') from public.projects;
select 'overview', string_agg(name,',') from public.project_overview;
\echo '-- member B cannot insert project into A'
insert into public.projects (team_id,name) values ('10000000-0000-0000-0000-000000000001','x');
\echo '-- member B cannot add a member'
insert into public.team_members values ('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-00000000000c','member');
\echo '-- member B cannot delete/rename'
delete from public.projects; update public.projects set name='hacked';
update public.teams set name='hacked';
select 'projects after member attempts', string_agg(name,',') from public.projects;
reset role;

\echo '== admin A (a) manages A, nothing in B'
set role authenticated; set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
select 'teams', string_agg(name,',') from public.teams;
select 'projects', string_agg(name,',') from public.projects;
insert into public.projects (team_id,name) values ('10000000-0000-0000-0000-000000000001','pA2');
update public.projects set name='pA-renamed' where name='pA';
\echo '-- admin A cannot insert into B'
insert into public.projects (team_id,name) values ('10000000-0000-0000-0000-000000000002','bad');
\echo '-- admin A cannot move project from A to B'
update public.projects set team_id='10000000-0000-0000-0000-000000000002' where name='pA2';
\echo '-- admin A cannot add self to B'
insert into public.team_members values ('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-00000000000a','admin');
\echo '-- admin A cannot touch B members or projects'
delete from public.team_members where team_id='10000000-0000-0000-0000-000000000002';
delete from public.projects where team_id='10000000-0000-0000-0000-000000000002';
\echo '-- admin A can manage members of A'
insert into public.team_members values ('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-00000000000c','member');
update public.team_members set role='admin' where user_id='00000000-0000-0000-0000-00000000000b';
delete from public.team_members where user_id='00000000-0000-0000-0000-00000000000c';
select 'members of A', string_agg(user_id::text||':'||role, ', ') from public.team_members where team_id='10000000-0000-0000-0000-000000000001';
reset role;

\echo '== non-member c sees only B; admin of B'
set role authenticated; set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000c';
select 'teams', string_agg(name,',') from public.teams;
select 'projects', string_agg(name,',') from public.projects;
select 'overview', string_agg(name,',') from public.project_overview;
reset role;

\echo '== ground truth (superuser)'
select name, team_id from public.projects order by name;
select 'pA2 present?', count(*) from public.projects where name='pA2';
EOF
docker rm -f rls-pg >/dev/null 2>&1; docker run -d --name rls-pg -e POSTGRES_PASSWORD=pw -p 55432:5432 postgres:15 >/dev/null && for i in $(seq 1 30); do docker exec rls-pg pg_isready -U postgres >/dev/null 2>&1 && break; sleep 1; done; docker exec rls-pg pg_isready -U postgres

